import type { Cents } from "../types/units";
import { type ParseResult, parseScaled } from "./decimal";

/**
 * Parse dollar text ("1,234.50", "$19.99") into integer cents. Extra decimals
 * are rounded half up, so "1.005" is 101 cents. Empty text returns the
 * explicit "empty" error; negatives return "negative".
 */
export const parseMoney = (text: string): ParseResult<Cents> => {
	const trimmed = text.trim();
	const result = parseScaled(
		trimmed.startsWith("$") ? trimmed.slice(1) : trimmed,
		2,
	);
	return result.ok ? { ok: true, value: result.value as Cents } : result;
};

/** Integer cents to "$1,234.56". Uses integer math only. */
export const formatMoney = (cents: Cents): string => {
	const dollars = Math.floor(cents / 100);
	const rest = cents - dollars * 100;
	const grouped = String(dollars).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
	return `$${grouped}.${String(rest).padStart(2, "0")}`;
};
/**
 * The single rounding helper. Integer half-up division for a non-negative
 * integer numerator: floor((2n + d) / (2d)). No float rounding is involved.
 * Throws RangeError if any intermediate value leaves the safe integer range.
 */
export const roundHalfUp = (numerator: number, denominator: number): number => {
	if (
		!Number.isSafeInteger(numerator) ||
		!Number.isSafeInteger(denominator) ||
		numerator < 0 ||
		denominator <= 0
	) {
		throw new RangeError(
			"roundHalfUp needs a non-negative integer numerator and a positive integer denominator",
		);
	}
	const doubled = numerator * 2 + denominator;
	if (
		!Number.isSafeInteger(doubled) ||
		!Number.isSafeInteger(2 * denominator)
	) {
		throw new RangeError("roundHalfUp overflowed the safe integer range");
	}
	return Math.floor(doubled / (2 * denominator));
};
import { roundHalfUp } from "./rounding";

export type ParseError = "empty" | "invalid" | "negative" | "too-large";

export type ParseResult<T> =
	| { ok: true; value: T }
	| { ok: false; error: ParseError };

const NUMBER_PATTERN = /^(-?)(\d*)(?:\.(\d*))?$/;

/**
 * Parses non-negative decimal text into an integer scaled by 10^decimals.
 * Splits at the decimal point and pads the fraction with zeros. If there are
 * more fraction digits than `decimals`, rounds half up with roundHalfUp.
 * Never uses parseFloat, multiplication by a float, or toFixed.
 * Thousands commas are ignored.
 */
export const parseScaled = (
	text: string,
	decimals: number,
): ParseResult<number> => {
	const cleaned = text.trim().replaceAll(",", "");
	if (cleaned === "") return { ok: false, error: "empty" };
	const match = NUMBER_PATTERN.exec(cleaned);
	if (!match) return { ok: false, error: "invalid" };
	const [, sign, whole = "", fraction = ""] = match;
	if (whole === "" && fraction === "") return { ok: false, error: "invalid" };
	if (sign === "-") return { ok: false, error: "negative" };
	// Keep one extra digit; for half-up only that digit decides the rounding.
	const extended = fraction.slice(0, decimals + 1).padEnd(decimals + 1, "0");
	const scaledByTen = Number(`${whole === "" ? "0" : whole}${extended}`);
	if (!Number.isSafeInteger(scaledByTen)) {
		return { ok: false, error: "too-large" };
	}
	return { ok: true, value: roundHalfUp(scaledByTen, 10) };
};
declare const centsBrand: unique symbol;
declare const microsBrand: unique symbol;

/** Integer number of cents. Never dollars. */
export type Cents = number & { readonly [centsBrand]: true };

/** Integer millionths of a fraction. 6.125% is 61250. */
export type Micros = number & { readonly [microsBrand]: true };
/** Integer cents. $2,400.00 is 240000. Local alias until the branded Cents type from the money primitives lands. */
export type MoneyCents = number;

/** Integer millionths. 1.40% is 14000 (1,000,000 is 100%). Local alias until the branded Micros type lands. */
export type RateMicros = number;

export type Confidence =
	| "low"
	| "low-to-moderate"
	| "moderate"
	| "not-applicable";

/** ISO calendar date, YYYY-MM-DD. */
export type IsoDate = string;

/** PRD 9.3: every default is stored with its source, as-of date and confidence. */
export interface DefaultRecord<T> {
	value: T;
	source: string;
	asOf: IsoDate;
	confidence: Confidence;
}
import { STATE_TAX_TABLE } from "./stateTaxTable";
import type { DefaultRecord, IsoDate, MoneyCents, RateMicros } from "./types";

/**
 * Registry of every illustrative default (PRD 9.2 and 9.3).
 * Money is integer cents, rates are integer millionths.
 * Changing a value requires a new `asOf` in the same change; the guard test
 * in defaults.test.ts fails otherwise.
 */

/** A default older than this many days is shown as "May be out of date". */
export const STALE_AFTER_DAYS = 365;

const MS_PER_DAY = 86_400_000;

const toUtcDay = (iso: IsoDate): number => {
	const [year = Number.NaN, month = Number.NaN, day = Number.NaN] = iso
		.split("-")
		.map(Number);
	return Date.UTC(year, month - 1, day);
};

/**
 * True when `asOf` is more than STALE_AFTER_DAYS before `today`.
 * Exactly 365 days is not stale. Staleness never blocks a calculation.
 */
export const isStale = (asOf: IsoDate, today: Date = new Date()): boolean => {
	const todayUtc = Date.UTC(
		today.getUTCFullYear(),
		today.getUTCMonth(),
		today.getUTCDate(),
	);
	return (todayUtc - toUtcDay(asOf)) / MS_PER_DAY > STALE_AFTER_DAYS;
};

export interface IndexPreset {
	id: "flat" | "plus-one-per-year" | "shock";
	label: string;
}

const AS_OF = "2026-10-30";

export const DEFAULTS = {
	stateTaxRates: STATE_TAX_TABLE,
	homeownersInsurance: {
		/** Annual, flat. Does not scale with home price. $2,400.00 per year. */
		value: 240000 as MoneyCents,
		source:
			"Four public 2026 estimates between $2,377 and $2,543, based on about $300,000 of dwelling coverage",
		asOf: AS_OF,
		confidence: "moderate",
	},
	pmiRate: {
		/** Annual rate on the loan amount. 0.75% per year. */
		value: 7500 as RateMicros,
		source:
			"Midpoint of the commonly cited 0.5% to 1.0% range. No authoritative rate matrix was found.",
		asOf: AS_OF,
		confidence: "low",
	},
	armTerms: {
		value: {
			/** 2.75% margin. */
			marginMicros: 27500 as RateMicros,
			/** Caps 2/1/5 in rate points: initial 2%, periodic 1%, lifetime 5%. */
			initialCapMicros: 20000 as RateMicros,
			periodicCapMicros: 10000 as RateMicros,
			lifetimeCapMicros: 50000 as RateMicros,
		},
		source:
			"Author's knowledge of typical 5/6 SOFR terms. Not checked against a Loan Estimate.",
		asOf: AS_OF,
		confidence: "low",
	},
	dtiThresholds: {
		value: {
			/** 28% front-end. */
			frontEndMicros: 280000 as RateMicros,
			/** 36% back-end. */
			backEndMicros: 360000 as RateMicros,
		},
		source: "Common industry rules of thumb. Not verified.",
		asOf: AS_OF,
		confidence: "moderate",
	},
	indexPathPresets: {
		value: [
			{ id: "flat", label: "Flat" },
			{ id: "plus-one-per-year", label: "+1 point per year" },
			{ id: "shock", label: "Shock" },
		] as IndexPreset[],
		source: "Product choice",
		asOf: AS_OF,
		confidence: "not-applicable",
	},
} satisfies Record<string, DefaultRecord<unknown>>;
import type { Cents, Micros } from "../types/units";
import { type ParseResult, parseScaled } from "./decimal";
import { roundHalfUp } from "./rounding";

/** Monthly interest denominator: 12 months x 1,000,000 micros. */
export const INTEREST_DENOMINATOR = 12_000_000;

/**
 * Parse percent text ("6.125", "6.125%") into integer millionths (61250).
 * 1% is 10,000 micros, so four percent decimals are exact; more are rounded
 * half up.
 */
export const parseRate = (text: string): ParseResult<Micros> => {
	const trimmed = text.trim();
	const result = parseScaled(
		trimmed.endsWith("%") ? trimmed.slice(0, -1) : trimmed,
		4,
	);
	return result.ok ? { ok: true, value: result.value as Micros } : result;
};

/**
 * Overflow policy: REJECT (no BigInt). The interest line computes
 * balance x micro x 2 + den, which must stay at or below
 * Number.MAX_SAFE_INTEGER (9,007,199,254,740,991). With a 12% rate this
 * allows balances of roughly $375 million, far above any real loan.
 */
export const isInterestSafe = (balance: Cents, rate: Micros): boolean =>
	Number.isSafeInteger(balance * rate * 2 + INTEREST_DENOMINATOR);

/**
 * Monthly interest in cents, integer half-up:
 * floor((B x micro x 2 + den) / (2 x den)). Throws RangeError when
 * isInterestSafe is false.
 */
export const monthlyInterest = (balance: Cents, rate: Micros): Cents => {
	if (!isInterestSafe(balance, rate)) {
		throw new RangeError("balance x rate exceeds the safe integer range");
	}
	return roundHalfUp(balance * rate, INTEREST_DENOMINATOR) as Cents;
};

/** Micros to percent text with 0 to 4 fixed decimals, rounded half up. 61250, 2 -> "6.13%". */
export const formatPercent = (rate: Micros, decimals = 2): string => {
	if (!Number.isInteger(decimals) || decimals < 0 || decimals > 4) {
		throw new RangeError("decimals must be an integer from 0 to 4");
	}
	const scaled = roundHalfUp(rate, 10 ** (4 - decimals));
	const text = String(scaled).padStart(decimals + 1, "0");
	const whole = decimals === 0 ? text : text.slice(0, -decimals);
	const fraction = decimals === 0 ? "" : `.${text.slice(-decimals)}`;
	return `${whole}${fraction}%`;
};

/** Micros to percent text without losing precision, minimum 2 decimals. 61250 -> "6.125%". */
export const formatRate = (rate: Micros): string => {
	const four = formatPercent(rate, 4).slice(0, -1);
	const trimmed = four.replace(/0{1,2}$/, "");
	return `${trimmed}%`;
};
